insert into public.rules (course_name,lesson_number,title,content,sort_order,rule_kind,summary) values
('Мединский курс (Том 3)','1','الإِعْرَابُ وَالبِنَاءُ وَعَلَامَاتُهُمَا (И‘раб, бина и падежные показатели)','<p><strong>Суть правила.</strong> Изменяемое слово меняет окончание из-за управляющего элемента; неизменяемое сохраняет форму. Здесь же: основные и второстепенные показатели, скрытый и‘раб, الحال, كِلَا/كِلْتَا, идафа и несклоняемые на танвин слова.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ المُدَرِّسُ</strong> — Пришёл преподаватель..</li><li><strong dir="rtl" lang="ar">سَأَلْتُ المُدَرِّسَ</strong> — Я спросил преподавателя..</li><li><strong dir="rtl" lang="ar">سَلَّمْتُ عَلَى المُدَرِّسِ</strong> — Я поприветствовал преподавателя..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">جَاءَ: فعل ماضٍ مبني على الفتح. المُدَرِّسُ: فاعل مرفوع وعلامة رفعه الضمة.</span></p>','1','rule','Изменяемое слово меняет окончание из-за управляющего элемента; неизменяемое сохраняет форму. Здесь же: основные и второстепенные показатели, скрытый и‘раб, الحال, كِلَا/كِلْتَا, идафа и несклоняемые на танвин слова.'),
('Мединский курс (Том 3)','2','الصَّرْفُ: الفِعْلُ الثُّلَاثِيُّ وَالمَبْنِيُّ لِلْمَجْهُولِ (Сарф: простой трёхбуквенный глагол и пассив)','<p><strong>Суть правила.</strong> Урок охватывает модели простого трёхбуквенного глагола, его настоящее время, пассив прошедшего и настоящего, а также расширенные модели и их значения. Форму определяют по корню и добавочным буквам.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">كُتِبَ الدَّرْسُ</strong> — Урок был написан..</li><li><strong dir="rtl" lang="ar">يُكْتَبُ الدَّرْسُ</strong> — Урок пишется..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كُتِبَ: فعل ماضٍ مبني للمجهول. الدَّرْسُ: نائب فاعل مرفوع بالضمة.</span></p>','1','rule','Урок охватывает модели простого трёхбуквенного глагола, его настоящее время, пассив прошедшего и настоящего, а также расширенные модели и их значения. Форму определяют по корню и добавочным буквам.'),
('Мединский курс (Том 3)','3','هَاءُ الضَّمِيرِ وَالنِّسْبَةُ وَالأَلْفُ الفَارِقَةُ (Ха местоимения, нисба и различительный алиф)','<p><strong>Суть правила.</strong> Ха местоимения присоединяется к имени, глаголу или предлогу; относительное прилагательное строится с يّ; различительный алиф пишется после واو الجماعة в глаголе и не произносится. Также закрепляются имена и грамматические термины урока.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كِتَابُهُ جَدِيدٌ</strong> — Его книга новая..</li><li><strong dir="rtl" lang="ar">هُمْ كَتَبُوا الدَّرْسَ</strong> — Они написали урок..</li><li><strong dir="rtl" lang="ar">هُوَ طَالِبٌ مِصْرِيٌّ</strong> — Он египетский студент..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كِتَابُ: مبتدأ مرفوع وهو مضاف. هُ: ضمير متصل في محل جر مضاف إليه. جَدِيدٌ: خبر مرفوع.</span></p>','1','rule','Ха местоимения присоединяется к имени, глаголу или предлогу; относительное прилагательное строится с يّ; различительный алиф пишется после واو الجماعة в глаголе и не произносится. Также закрепляются имена и грамматические термины урока.'),
('Мединский курс (Том 3)','4','اِسْمُ الفَاعِلِ وَاِسْمُ المَفْعُولِ مِنَ الصَّحِيحِ (Причастия от правильного глагола)','<p><strong>Суть правила.</strong> Действительное причастие от трёхбуквенного правильного глагола обычно имеет модель فَاعِل, страдательное - مَفْعُول. В урок включены سالم, مهموز, مضاعف и частица مَا الحجازية.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا طَالِبٌ كَاتِبٌ</strong> — Это пишущий студент..</li><li><strong dir="rtl" lang="ar">هَذَا دَرْسٌ مَكْتُوبٌ</strong> — Это написанный урок..</li><li><strong dir="rtl" lang="ar">مَا الطَّالِبُ غَائِبًا</strong> — Студент не отсутствует..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">هَذَا: اسم إشارة مبني في محل رفع مبتدأ. دَرْسٌ: خبر مرفوع. مَكْتُوبٌ: نعت مرفوع.</span></p>','1','rule','Действительное причастие от трёхбуквенного правильного глагола обычно имеет модель فَاعِل, страдательное - مَفْعُول. В урок включены سالم, مهموز, مضاعف и частица مَا الحجازية.'),
('Мединский курс (Том 3)','5','اِسْمَا الفَاعِلِ وَالمَفْعُولِ مِنَ المُعْتَلِّ (Причастия от слабого глагола)','<p><strong>Суть правила.</strong> Формы слабого глагола требуют внимания к слабой букве: قَالَ - قَائِل, دَعَا - دَاعٍ, قَالَ - مَقُول. Урок противопоставляет слабые и правильные формы и закрепляет их в падежных позициях.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هُوَ دَاعٍ إِلَى الخَيْرِ</strong> — Он призывающий к добру..</li><li><strong dir="rtl" lang="ar">هَذَا قَوْلٌ مَقُولٌ</strong> — Это сказанное высказывание..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ رَجُلًا قَائِلًا الحَقَّ</strong> — Я увидел человека, говорящего правду..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">دَاعٍ: خبر مرفوع بضمة مقدرة على الياء المحذوفة، والتنوين عوض عن الياء.</span></p>','1','rule','Формы слабого глагола требуют внимания к слабой букве: قَالَ - قَائِل, دَعَا - دَاعٍ, قَالَ - مَقُول. Урок противопоставляет слабые и правильные формы и закрепляет их в падежных позициях.'),
('Мединский курс (Том 3)','6','اِسْمَا الزَّمَانِ وَالمَكَانِ (Имена времени и места)','<p><strong>Суть правила.</strong> Эти производные имена называют время или место действия. Встречаются модели مَفْعِل и مَفْعَل, а у расширенных глаголов - форма от настоящего времени с начальным мимом.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">هَذَا مَوْعِدُ الدَّرْسِ</strong> — Это время урока..</li><li><strong dir="rtl" lang="ar">المَسْجِدُ مَكَانُ الصَّلَاةِ</strong> — Мечеть - место молитвы..</li><li><strong dir="rtl" lang="ar">ذَهَبْتُ إِلَى المَكْتَبِ</strong> — Я пошёл в кабинет..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">هَذَا: مبتدأ. مَوْعِدُ: خبر مرفوع وهو مضاف. الدَّرْسِ: مضاف إليه مجرور.</span></p>','1','rule','Эти производные имена называют время или место действия. Встречаются модели مَفْعِل и مَفْعَل, а у расширенных глаголов - форма от настоящего времени с начальным мимом.'),
('Мединский курс (Том 3)','7','اِسْمُ الآلَةِ (Имя орудия)','<p><strong>Суть правила.</strong> Имя орудия называет предмет, которым выполняют действие. Частые модели: مِفْعَال, مِفْعَل, مِفْعَلَة. Не каждое орудие образуется механически, поэтому словарная форма остаётся важной.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">فَتَحْتُ البَابَ بِالمِفْتَاحِ</strong> — Я открыл дверь ключом..</li><li><strong dir="rtl" lang="ar">كَتَبْتُ بِالقَلَمِ</strong> — Я написал ручкой..</li><li><strong dir="rtl" lang="ar">هَذِهِ مِكْنَسَةٌ</strong> — Это метла..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">فَتَحْتُ: فعل وفاعل. البَابَ: مفعول به منصوب. بِالمِفْتَاحِ: جار ومجرور متعلق بالفعل.</span></p>','1','rule','Имя орудия называет предмет, которым выполняют действие. Частые модели: مِفْعَال, مِفْعَل, مِفْعَلَة. Не каждое орудие образуется механически, поэтому словарная форма остаётся важной.'),
('Мединский курс (Том 3)','8','المَعْرِفَةُ وَالنَّكِرَةُ (Определённое и неопределённое имя)','<p><strong>Суть правила.</strong> Неопределённое имя называет предмет вообще, определённое указывает на известный предмет. Определённость создают ال, имя собственное, местоимение, указательное или относительное слово, а также идафа к определённому имени.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ رَجُلٌ</strong> — Пришёл какой-то мужчина..</li><li><strong dir="rtl" lang="ar">جَاءَ الرَّجُلُ</strong> — Пришёл этот мужчина..</li><li><strong dir="rtl" lang="ar">هَذَا كِتَابُ الطَّالِبِ</strong> — Это книга студента..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">رَجُلٌ: فاعل مرفوع ونكرة.</span></p>','1','rule','Неопределённое имя называет предмет вообще, определённое указывает на известный предмет. Определённость создают ال, имя собственное, местоимение, указательное или относительное слово, а также идафа к определённому имени.'),
('Мединский курс (Том 3)','9','حَذْفُ نُونِ المُثَنَّى وَجَمْعِ المُذَكَّرِ السَّالِمِ (Удаление нуна в идафе)','<p><strong>Суть правила.</strong> При идафе двойственное число и правильное мужское множественное теряют нун: كِتَابَا الطَّالِبِ, مُسْلِمُو البَلَدِ. Урок также закрепляет كِلَا/كِلْتَا и указательные слова.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ مُسْلِمُو البَلَدِ</strong> — Пришли мусульмане страны..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ كِتَابَيْ الطَّالِبِ</strong> — Я увидел две книги студента..</li><li><strong dir="rtl" lang="ar">كِلَا الطَّالِبَيْنِ مُجْتَهِدٌ</strong> — Оба студента прилежны..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">مُسْلِمُو: فاعل مرفوع بالواو وهو مضاف، وحذفت النون للإضافة. البَلَدِ: مضاف إليه.</span></p>','1','rule','При идафе двойственное число и правильное мужское множественное теряют нун: كِتَابَا الطَّالِبِ, مُسْلِمُو البَلَدِ. Урок также закрепляет كِلَا/كِلْتَا и указательные слова.'),
('Мединский курс (Том 3)','10','الجُمْلَةُ الاِسْمِيَّةُ وَالفِعْلِيَّةُ وَالمَصْدَرُ المُؤَوَّلُ (Типы предложений и развёрнутый масдар)','<p><strong>Суть правила.</strong> Именное предложение начинается с имени, глагольное - с глагола. Оборот أَنْ + المضارع может занимать место масдара и получает синтаксическую роль как единое целое.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">العِلْمُ نَافِعٌ</strong> — Знание полезно..</li><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">أُرِيدُ أَنْ أَتَعَلَّمَ</strong> — Я хочу учиться..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">أُرِيدُ: فعل مضارع مرفوع وفاعله مستتر. أَنْ أَتَعَلَّمَ: مصدر مؤول في محل نصب مفعول به.</span></p>','1','rule','Именное предложение начинается с имени, глагольное - с глагола. Оборот أَنْ + المضارع может занимать место масдара и получает синтаксическую роль как единое целое.'),
('Мединский курс (Том 3)','11','المُبْتَدَأُ وَالخَبَرُ (Подлежащее и сказуемое)','<p><strong>Суть правила.</strong> Мубтада - то, о чём говорится, хабар - сообщение о нём. Оба обычно в именительном падеже; хабар бывает одиночным словом, предложением или предложной конструкцией.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">العِلْمُ نَافِعٌ</strong> — Знание полезно..</li><li><strong dir="rtl" lang="ar">الطَّالِبُ فِي الفَصْلِ</strong> — Студент в классе..</li><li><strong dir="rtl" lang="ar">أَبِي مُدَرِّسٌ</strong> — Мой отец преподаватель..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">العِلْمُ: مبتدأ مرفوع. نَافِعٌ: خبر مرفوع.</span></p>','1','rule','Мубтада - то, о чём говорится, хабар - сообщение о нём. Оба обычно в именительном падеже; хабар бывает одиночным словом, предложением или предложной конструкцией.'),
('Мединский курс (Том 3)','12','المَفْعُولُ فِيهِ (Обстоятельство времени и места)','<p><strong>Суть правила.</strong> ظرف زمان или مكان называет время либо место действия. Он отвечает на «когда?» или «где?»; без предлога обычно имеет винительный падеж. В уроке разбираются قبل, بعد, لدى и другие обстоятельства.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">سَافَرْتُ لَيْلًا</strong> — Я путешествовал ночью..</li><li><strong dir="rtl" lang="ar">جَلَسْتُ أَمَامَ المُدَرِّسِ</strong> — Я сел перед преподавателем..</li><li><strong dir="rtl" lang="ar">دَرَسْتُ يَوْمَ الجُمُعَةِ</strong> — Я учился в пятницу..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">لَيْلًا: ظرف زمان منصوب.</span></p>','1','rule','ظرف زمان или مكان называет время либо место действия. Он отвечает на «когда?» или «где?»; без предлога обычно имеет винительный падеж. В уроке разбираются قبل, بعد, لدى и другие обстоятельства.'),
('Мединский курс (Том 3)','13','لَامُ الأَمْرِ وَأَدَوَاتُ الجَزْمِ (Лам приказа и частицы усечения)','<p><strong>Суть правила.</strong> Лам приказа требует усечённого настоящего глагола: لِيَكْتُبْ. Урок включает لَمْ, لَمَّا, الطلب и обращение, а также признаки усечения.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">لِيَكْتُبْ الطَّالِبُ الدَّرْسَ</strong> — Пусть студент напишет урок..</li><li><strong dir="rtl" lang="ar">لَمْ يَذْهَبْ خَالِدٌ</strong> — Халид не пошёл..</li><li><strong dir="rtl" lang="ar">فَلْيَقُلْ خَيْرًا</strong> — Пусть он говорит доброе..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">لِيَكْتُبْ: لام الأمر جازمة، يكتب فعل مضارع مجزوم بالسكون.</span></p>','1','rule','Лам приказа требует усечённого настоящего глагола: لِيَكْتُبْ. Урок включает لَمْ, لَمَّا, الطلب и обращение, а также признаки усечения.'),
('Мединский курс (Том 3)','14','أَدَوَاتُ الشَّرْطِ غَيْرُ الجَازِمَةِ (Неусекающие условные частицы)','<p><strong>Суть правила.</strong> Иِذَا, لَوْلَا и похожие конструкции выражают условие, но не усекaют настоящее время. Важно отличать их от условных частиц, которые требуют джазм.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِذَا جَاءَ المُدَرِّسُ قُمْنَا</strong> — Когда придёт преподаватель, мы встанем..</li><li><strong dir="rtl" lang="ar">لَوْلَا العِلْمُ مَا تَقَدَّمْنَا</strong> — Если бы не знание, мы бы не продвинулись..</li><li><strong dir="rtl" lang="ar">كُلَّمَا جَاءَ ضَيْفٌ أَكْرَمْنَاهُ</strong> — Когда бы ни пришёл гость, мы его чествуем..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">إِذَا: ظرف لما يستقبل متضمن معنى الشرط.</span></p>','1','rule','Иِذَا, لَوْلَا и похожие конструкции выражают условие, но не усекaют настоящее время. Важно отличать их от условных частиц, которые требуют джазм.'),
('Мединский курс (Том 3)','15','أَدَوَاتُ الشَّرْطِ الجَازِمَةِ (Усекающие условные частицы)','<p><strong>Суть правила.</strong> После إِنْ, مَنْ, مَا и مَهْمَا обычно усечены глагол условия и его ответ. В ряде конструкций ответ связывается с فاء.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِنْ تَجْتَهِدْ تَنْجَحْ</strong> — Если будешь стараться, преуспеешь..</li><li><strong dir="rtl" lang="ar">مَنْ يَصْدُقْ يُحْتَرَمْ</strong> — Кто говорит правду, того уважают..</li><li><strong dir="rtl" lang="ar">مَهْمَا تَفْعَلْ تُجْزَ بِهِ</strong> — Что бы ты ни сделал, за это получишь воздаяние..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">إِنْ: حرف شرط جازم. تَجْتَهِدْ: فعل الشرط مجزوم. تَنْجَحْ: جواب الشرط مجزوم.</span></p>','1','rule','После إِنْ, مَنْ, مَا и مَهْمَا обычно усечены глагол условия и его ответ. В ряде конструкций ответ связывается с فاء.'),
('Мединский курс (Том 3)','16','أَوْزَانُ الثُّلَاثِيِّ وَجُمُوعُ التَّكْسِيرِ (Модели простого глагола и ломаное множественное)','<p><strong>Суть правила.</strong> У простого трёхбуквенного глагола несколько моделей настоящего времени. Ломаное множественное меняет внутренний рисунок слова, поэтому обе формы учат вместе. Урок также вводит уменьшительные формы и значения частиц.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ يَكْتُبُ</strong> — Он написал - он пишет..</li><li><strong dir="rtl" lang="ar">جَلَسَ يَجْلِسُ</strong> — Он сел - он сидит..</li><li><strong dir="rtl" lang="ar">كِتَابٌ كُتُبٌ</strong> — Книга - книги..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كَتَبَ: فعل ماضٍ. يَكْتُبُ: مضارع مرفوع.</span></p>','1','rule','У простого трёхбуквенного глагола несколько моделей настоящего времени. Ломаное множественное меняет внутренний рисунок слова, поэтому обе формы учат вместе. Урок также вводит уменьшительные формы и значения частиц.'),
('Мединский курс (Том 3)','17','بَابُ أَفْعَلَ وَالمَفْعُولَانِ (Четвёртая порода и два дополнения)','<p><strong>Суть правила.</strong> Четвёртая порода строится по модели أَفْعَلَ и часто придаёт причинный смысл. Часть глаголов требует два дополнения: кому? и что? Урок закрепляет хамзу в начале и особенности переходности.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">أَخْرَجَ المُدَرِّسُ الطَّالِبَ</strong> — Преподаватель вывел студента..</li><li><strong dir="rtl" lang="ar">أَعْطَيْتُ الطَّالِبَ كِتَابًا</strong> — Я дал студенту книгу..</li><li><strong dir="rtl" lang="ar">أَرَيْتُهُ البَيْتَ</strong> — Я показал ему дом..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">أَعْطَيْتُ: فعل وفاعل. الطَّالِبَ: مفعول به أول. كِتَابًا: مفعول به ثانٍ.</span></p>','1','rule','Четвёртая порода строится по модели أَفْعَلَ и часто придаёт причинный смысл. Часть глаголов требует два дополнения: кому? и что? Урок закрепляет хамзу в начале и особенности переходности.'),
('Мединский курс (Том 4)','1','اللَّازِمُ وَالمُتَعَدِّي وَطُرُقُ التَّعْدِيَةِ (Непереходный, переходный и способы переходности)','<p><strong>Суть правила.</strong> Переходный глагол берёт прямое дополнение, непереходный описывает законченное действие. Урок также разбирает, как предлог, хамза или удвоение делают значение переходным, и отдельные значения باب فَعَلَ.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">كَتَبَ الطَّالِبُ الدَّرْسَ</strong> — Студент написал урок..</li><li><strong dir="rtl" lang="ar">ذَهَبَ الطَّالِبُ إِلَى المَكْتَبَةِ</strong> — Студент пошёл в библиотеку..</li><li><strong dir="rtl" lang="ar">أَذْهَبْتُ الطَّالِبَ إِلَى المَكْتَبَةِ</strong> — Я отправил студента в библиотеку..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كَتَبَ: فعل ماضٍ. الطَّالِبُ: فاعل. الدَّرْسَ: مفعول به.</span></p>','1','rule','Переходный глагол берёт прямое дополнение, непереходный описывает законченное действие. Урок также разбирает, как предлог, хамза или удвоение делают значение переходным, и отдельные значения باب فَعَلَ.'),
('Мединский курс (Том 4)','2','بَابُ فَاعَلَ (Третья порода: участие и направленное действие)','<p><strong>Суть правила.</strong> Форма فَاعَلَ часто выражает участие двух сторон или действие по отношению к другому. Урок также включает лям усиления, حذف نون, مذكر/مؤنث и некоторые масдары. Точное значение каждого глагола проверяется по словарю.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">شَارَكَ الطَّالِبُ فِي المُسَابَقَةِ</strong> — Студент участвовал в соревновании..</li><li><strong dir="rtl" lang="ar">سَاعَدَ الأَبُ ابْنَهُ</strong> — Отец помог сыну..</li><li><strong dir="rtl" lang="ar">قَابَلْتُ صَدِيقِي</strong> — Я встретил друга..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">شَارَكَ: فعل ماضٍ. الطَّالِبُ: فاعل. فِي المُسَابَقَةِ: جار ومجرور.</span></p>','1','rule','Форма فَاعَلَ часто выражает участие двух сторон или действие по отношению к другому. Урок также включает лям усиления, حذف نون, مذكر/مؤنث и некоторые масдары. Точное значение каждого глагола проверяется по словарю.'),
('Мединский курс (Том 4)','3','بَابُ تَفَعَّلَ (Пятая порода: действие над собой)','<p><strong>Суть правила.</strong> Тَفَعَّلَ часто передаёт освоение, постепенное изменение или действие над собой. В уроке разбираются حذف إحدى التاءين в настоящем времени, прошедшее с لا и формы الحَيْفِيَّة.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">تَعَلَّمَ الوَلَدُ العَرَبِيَّةَ</strong> — Мальчик изучал арабский..</li><li><strong dir="rtl" lang="ar">تَذَكَّرْتُ الدَّرْسَ</strong> — Я вспомнил урок..</li><li><strong dir="rtl" lang="ar">لا تَتَكَلَّمْ كَثِيرًا</strong> — Не говори много..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">تَعَلَّمَ: فعل ماضٍ. الوَلَدُ: فاعل. العَرَبِيَّةَ: مفعول به.</span></p>','1','rule','Тَفَعَّلَ часто передаёт освоение, постепенное изменение или действие над собой. В уроке разбираются حذف إحدى التاءين в настоящем времени, прошедшее с لا и формы الحَيْفِيَّة.'),
('Мединский курс (Том 4)','4','بَابُ تَفَاعَلَ (Шестая порода: взаимное действие)','<p><strong>Суть правила.</strong> Тَفَاعَلَ обычно показывает взаимность. Урок дополнительно включает حذف إحدى التاءين, لَا النافية للجنس, جمع أفعل и фа ответа.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">تَعَاوَنَ الطُّلَّابُ فِي العَمَلِ</strong> — Студенты сотрудничали..</li><li><strong dir="rtl" lang="ar">تَشَاوَرَ الرَّجُلَانِ</strong> — Двое мужчин посоветовались..</li><li><strong dir="rtl" lang="ar">لا رَجُلَ فِي الفَصْلِ</strong> — В классе нет ни одного мужчины..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">تَعَاوَنَ: فعل ماضٍ. الطُّلَّابُ: فاعل مرفوع.</span></p>','1','rule','Тَفَاعَلَ обычно показывает взаимность. Урок дополнительно включает حذف إحدى التاءين, لَا النافية للجنس, جمع أفعل и фа ответа.'),
('Мединский курс (Том 4)','5','بَابُ اِنْفَعَلَ (Седьмая порода и возвратное значение)','<p><strong>Суть правила.</strong> اِنْفَعَلَ часто выражает изменение состояния и обычно непереходен. В уроке также: لَوْلَا, ближайшее указательное слово, восклицательная модель и идафа к обстоятельству.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِنْكَسَرَ الزُّجَاجُ</strong> — Стекло разбилось..</li><li><strong dir="rtl" lang="ar">اِنْفَتَحَ البَابُ</strong> — Дверь открылась..</li><li><strong dir="rtl" lang="ar">مَا أَجْمَلَ السَّمَاءَ</strong> — Как прекрасно небо!.</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">اِنْكَسَرَ: فعل ماضٍ. الزُّجَاجُ: فاعل مرفوع.</span></p>','1','rule','اِنْفَعَلَ часто выражает изменение состояния и обычно непереходен. В уроке также: لَوْلَا, ближайшее указательное слово, восклицательная модель и идафа к обстоятельству.'),
('Мединский курс (Том 4)','6','بَابُ اِفْتَعَلَ (Восьмая порода и её особенности)','<p><strong>Суть правила.</strong> В اِفْتَعَلَ добавочная ت стоит после первой коренной. Урок включает إذا الفجائية, глагол ظَنَّ, выражения دَخَلَ فِي и усиленные формы действительного причастия.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِجْتَهَدَ الطَّالِبُ</strong> — Студент старался..</li><li><strong dir="rtl" lang="ar">اِشْتَرَيْتُ كِتَابًا</strong> — Я купил книгу..</li><li><strong dir="rtl" lang="ar">خَرَجْتُ فَإِذَا صَدِيقِي بِالبَابِ</strong> — Я вышел, и вдруг мой друг у двери..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">اِجْتَهَدَ: فعل ماضٍ. الطَّالِبُ: فاعل.</span></p>','1','rule','В اِفْتَعَلَ добавочная ت стоит после первой коренной. Урок включает إذا الفجائية, глагол ظَنَّ, выражения دَخَلَ فِي и усиленные формы действительного причастия.'),
('Мединский курс (Том 4)','7','بَابُ أَفْعَلَ وَالأَفْعَالُ النَّاقِصَةُ (Четвёртая порода и особые глаголы)','<p><strong>Суть правила.</strong> В уроке закрепляется أَفْعَلَ, а также формы رَأَى, عَسَى и مَا المَصْدَرِيَّة. У этих слов есть особые изменения, которые удобнее учить готовыми моделями в контексте.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">أَخْرَجَ الوَلَدُ الكِتَابَ</strong> — Мальчик вынес книгу..</li><li><strong dir="rtl" lang="ar">عَسَى أَنْ يَهْدِيَنِي رَبِّي</strong> — Быть может, Господь наставит меня..</li><li><strong dir="rtl" lang="ar">رَأَيْتُ القَمَرَ</strong> — Я увидел луну..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">عَسَى: فعل ماضٍ ناقص جامد. أَنْ يَهْدِيَنِي: مصدر مؤول في محل نصب خبرها.</span></p>','1','rule','В уроке закрепляется أَفْعَلَ, а также формы رَأَى, عَسَى и مَا المَصْدَرِيَّة. У этих слов есть особые изменения, которые удобнее учить готовыми моделями в контексте.'),
('Мединский курс (Том 4)','8','بَابُ اِسْتَفْعَلَ وَنَوَاصِبُ المُضَارِعِ (Десятая порода и винительное состояние настоящего)','<p><strong>Суть правила.</strong> اِسْتَفْعَلَ часто выражает просьбу или поиск. Урок дополнительно разбирает كَيْ, إِذَنْ, отрицание прошлого через لا, формы Я, جمع الاسم المنقوص и نواصب المضارع.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِسْتَغْفَرَ المُسْلِمُ رَبَّهُ</strong> — Мусульманин просил у Господа прощения..</li><li><strong dir="rtl" lang="ar">جِئْتُ كَيْ أَتَعَلَّمَ</strong> — Я пришёл, чтобы учиться..</li><li><strong dir="rtl" lang="ar">لَنْ أَتَأَخَّرَ</strong> — Я не опоздаю..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كَيْ: حرف نصب وتعليل. أَتَعَلَّمَ: مضارع منصوب بالفتحة.</span></p>','1','rule','اِسْتَفْعَلَ часто выражает просьбу или поиск. Урок дополнительно разбирает كَيْ, إِذَنْ, отрицание прошлого через لا, формы Я, جمع الاسم المنقوص и نواصب المضارع.'),
('Мединский курс (Том 4)','9','الفِعْلُ الرُّبَاعِيُّ وَضَمِيرُ الفَصْلِ (Четырёхбуквенный глагол и разделительное местоимение)','<p><strong>Суть правила.</strong> Четырёхбуквенная основа имеет собственные модели. В уроке также рассматриваются ضمير الفصل, استفهام с хамзой перед союзом, مِنْ التبعيضية, слитное ياء المتكلم и слабый удвоенный глагол.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">دَحْرَجَ الوَلَدُ الكُرَةَ</strong> — Мальчик покатил мяч..</li><li><strong dir="rtl" lang="ar">إِنَّ هَذَا لَهُوَ الحَقُّ</strong> — Поистине, это и есть истина..</li><li><strong dir="rtl" lang="ar">أَمُحَمَّدٌ جَاءَ أَمْ عَلِيٌّ</strong> — Мухаммад пришёл или Али?.</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">دَحْرَجَ: فعل ماضٍ. الوَلَدُ: فاعل. الكُرَةَ: مفعول به.</span></p>','1','rule','Четырёхбуквенная основа имеет собственные модели. В уроке также рассматриваются ضمير الفصل, استفهام с хамзой перед союзом, مِنْ التبعيضية, слитное ياء المتكلم и слабый удвоенный глагол.'),
('Мединский курс (Том 4)','10','أَقْسَامُ الضَّمَائِرِ وَضَمَائِرُ النَّصْبِ (Виды местоимений и отдельные объектные формы)','<p><strong>Суть правила.</strong> Урок систематизирует отдельные, слитные и скрытые местоимения; отдельно объясняет إِيَّا и местоименную ха. Также рассматриваются модели масдара простого глагола.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">إِيَّاكَ نَعْبُدُ</strong> — Тебе одному мы поклоняемся..</li><li><strong dir="rtl" lang="ar">رَأَيْتُهُ فِي السُّوقِ</strong> — Я увидел его на рынке..</li><li><strong dir="rtl" lang="ar">كِتَابُهَا جَدِيدٌ</strong> — Её книга новая..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">إِيَّاكَ: ضمير نصب منفصل في محل نصب مفعول به مقدم. نَعْبُدُ: فعل وفاعل.</span></p>','1','rule','Урок систематизирует отдельные, слитные и скрытые местоимения; отдельно объясняет إِيَّا и местоименную ха. Также рассматриваются модели масдара простого глагола.'),
('Мединский курс (Том 4)','11','المَفْعُولُ المُطْلَقُ (Абсолютное дополнение и виды масдара)','<p><strong>Суть правила.</strong> Маф‘уль мутлак - масдар того же глагола, который усиливает действие, указывает число или способ. В уроке сопоставляются масдар раза, вида, мими и обычный масдар.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">شَكَرْتُهُ شُكْرًا</strong> — Я искренне поблагодарил его..</li><li><strong dir="rtl" lang="ar">ضَرَبْتُهُ ضَرْبَتَيْنِ</strong> — Я ударил его два раза..</li><li><strong dir="rtl" lang="ar">جَلَسْتُ جُلُوسَ المُؤَدَّبِ</strong> — Я сел как воспитанный человек..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">شُكْرًا: مفعول مطلق منصوب.</span></p>','1','rule','Маф‘уль мутлак - масдар того же глагола, который усиливает действие, указывает число или способ. В уроке сопоставляются масдар раза, вида, мими и обычный масдар.'),
('Мединский курс (Том 4)','12','المَفْعُولُ لِأَجْلِهِ وَلَا العَاطِفَةُ (Дополнение причины и соединительное «не»)','<p><strong>Суть правила.</strong> Маф‘уль ли-аджлихи называет внутреннюю причину действия и обычно является масдаром в винительном падеже. Урок также включает لَا, которая соединяет и отрицает следующий элемент, и частицы побуждения.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">دَرَسْتُ رَغْبَةً فِي العِلْمِ</strong> — Я учился из стремления к знанию..</li><li><strong dir="rtl" lang="ar">وَقَفْتُ اِحْتِرَامًا لِلْمُعَلِّمِ</strong> — Я встал из уважения к учителю..</li><li><strong dir="rtl" lang="ar">أُحِبُّ العِلْمَ لَا الجَهْلَ</strong> — Я люблю знание, а не невежество..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">رَغْبَةً: مفعول لأجله منصوب.</span></p>','1','rule','Маф‘уль ли-аджлихи называет внутреннюю причину действия и обычно является масдаром в винительном падеже. Урок также включает لَا, которая соединяет и отрицает следующий элемент, и частицы побуждения.'),
('Мединский курс (Том 4)','13','التَّمْيِيزُ وَالتَّعَجُّبُ (Уточнение и восклицание)','<p><strong>Суть правила.</strong> Тамйиз снимает неясность после числа, меры, веса или сравнительной степени. Восклицательная модель مَا أَفْعَلَ передаёт сильное восхищение. Урок также возвращается к моделям масдара.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">اِشْتَرَيْتُ عِشْرِينَ كِتَابًا</strong> — Я купил двадцать книг..</li><li><strong dir="rtl" lang="ar">مُحَمَّدٌ أَكْثَرُ عِلْمًا</strong> — Мухаммад более знающий..</li><li><strong dir="rtl" lang="ar">مَا أَجْمَلَ القَمَرَ</strong> — Как прекрасна луна!.</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">كِتَابًا: تمييز منصوب.</span></p>','1','rule','Тамйиз снимает неясность после числа, меры, веса или сравнительной степени. Восклицательная модель مَا أَفْعَلَ передаёт сильное восхищение. Урок также возвращается к моделям масдара.'),
('Мединский курс (Том 4)','14','الحَالُ (Обстоятельство состояния)','<p><strong>Суть правила.</strong> Халь описывает временное состояние участника действия и обычно неопределёнен и винителен. Урок также разбирает множественное числа на فَاعِل и فُعُول и масдары трёхбуквенного глагола.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطَّالِبُ مُبْتَسِمًا</strong> — Студент пришёл улыбаясь..</li><li><strong dir="rtl" lang="ar">دَخَلَ الوَلَدُ بَاكِيًا</strong> — Мальчик вошёл плача..</li><li><strong dir="rtl" lang="ar">رَجَعَ المُسَافِرُ مُتْعَبًا</strong> — Путник вернулся уставшим..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">مُبْتَسِمًا: حال منصوب.</span></p>','1','rule','Халь описывает временное состояние участника действия и обычно неопределёнен и винителен. Урок также разбирает множественное числа на فَاعِل и فُعُول и масдары трёхбуквенного глагола.'),
('Мединский курс (Том 4)','15','الاِسْتِثْنَاءُ (Исключение)','<p><strong>Суть правила.</strong> Исключение с إِلَّا выделяет то, что не входит в общую группу. В уроке также: جمع دينار, скрытое местоимение в хабар كَانَ и частица начала. Форма исключаемого зависит от полноты и отрицания предложения.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">جَاءَ الطُّلَّابُ إِلَّا خَالِدًا</strong> — Пришли студенты, кроме Халида..</li><li><strong dir="rtl" lang="ar">مَا جَاءَ أَحَدٌ إِلَّا خَالِدٌ</strong> — Никто не пришёл, кроме Халида..</li><li><strong dir="rtl" lang="ar">قَرَأْتُ الكُتُبَ إِلَّا كِتَابًا</strong> — Я прочитал книги, кроме одной книги..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">خَالِدًا: مستثنى منصوب بإلا.</span></p>','1','rule','Исключение с إِلَّا выделяет то, что не входит в общую группу. В уроке также: جمع دينار, скрытое местоимение в хабар كَانَ и частица начала. Форма исключаемого зависит от полноты и отрицания предложения.'),
('Мединский курс (Том 4)','16','نُونُ التَّوْكِيدِ (Нун усиления)','<p><strong>Суть правила.</strong> Нун усиления присоединяется к глаголу для сильного подчёркивания. В уроке закрепляются тяжёлая и лёгкая формы, باء الابتداء и их место в ответе клятвы.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">وَاللَّهِ لَأَجْتَهِدَنَّ</strong> — Клянусь Аллахом, я непременно буду стараться..</li><li><strong dir="rtl" lang="ar">لَيَكْتُبَنَّ الطَّالِبُ</strong> — Студент непременно напишет..</li><li><strong dir="rtl" lang="ar">لَا تَكْذِبَنَّ</strong> — Ни в коем случае не лги..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">لَأَجْتَهِدَنَّ: لام جواب القسم، مضارع مبني على الفتح لاتصاله بنون التوكيد.</span></p>','1','rule','Нун усиления присоединяется к глаголу для сильного подчёркивания. В уроке закрепляются тяжёлая и лёгкая формы, باء الابتداء и их место в ответе клятвы.'),
('Мединский курс (Том 4)','17','المَمْنُوعُ مِنَ الصَّرْفِ (Несклоняемое на танвин имя)','<p><strong>Суть правила.</strong> Такие имена не принимают танвин и без ال или идафы имеют фатху в родительном падеже. Заключительный урок закрепляет модели и причины منع الصرف.</p><p><strong>Как применять.</strong> Сначала найдите управляющее слово и роль конструкции; затем проверьте огласовку, окончание и перевод целиком.</p><p><strong>Три примера.</strong></p><ol><li><strong dir="rtl" lang="ar">صَلَّيْتُ فِي مَسَاجِدَ كَثِيرَةٍ</strong> — Я молился во многих мечетях..</li><li><strong dir="rtl" lang="ar">مَرَرْتُ بِأَحْمَدَ</strong> — Я прошёл мимо Ахмада..</li><li><strong dir="rtl" lang="ar">صَلَّيْتُ فِي المَسَاجِدِ الكَبِيرَةِ</strong> — Я молился в больших мечетях..</li></ol><p><strong>Полный разбор إعراب первого примера.</strong><br><span dir="rtl" lang="ar">مَسَاجِدَ: اسم مجرور بالفتحة نيابة عن الكسرة لأنه ممنوع من الصرف.</span></p>','1','rule','Такие имена не принимают танвин и без ال или идафы имеют фатху в родительном падеже. Заключительный урок закрепляет модели и причины منع الصرف.');
